$ErrorActionPreference = "Stop"
Set-Location $PSScriptRoot

Write-Host "============================================================"
Write-Host "GeoPilot Terrain DEM Ingestion V1"
Write-Host "GeoTIFF upload + strict validation + project/site provenance"
Write-Host "NO migration - NO frontend change - Track B protected"
Write-Host "============================================================"
Write-Host ""

docker compose config --services *> $null
if ($LASTEXITCODE -ne 0) { throw "Run from geopilot_v7 root and ensure Docker is running." }

Write-Host "[1/7] Applying controlled backend patch..."
$payload = ""
docker compose run --rm --no-deps -v "${PWD}:/workspace" -w /workspace backend python -c "import base64;exec(base64.b64decode('$payload'))"
if ($LASTEXITCODE -ne 0) { throw "Patch step failed" }

Write-Host ""
Write-Host "[2/7] Python compile gate..."
docker compose run --rm --no-deps -v "${PWD}:/workspace" -w /workspace/backend backend python -m compileall app/api/v1/terrain.py app/services/terrain_ingestion.py app/services/terrain_analysis.py tests/test_terrain_ingestion.py
if ($LASTEXITCODE -ne 0) { throw "Compile gate failed" }

Write-Host ""
Write-Host "[3/7] DEM ingestion tests..."
docker compose run --rm --no-deps -v "${PWD}:/workspace" -w /workspace/backend -e PYTHONPATH=/workspace/backend backend pytest -q tests/test_terrain_ingestion.py tests/test_terrain_analysis.py
if ($LASTEXITCODE -ne 0) { throw "Terrain ingestion tests failed" }

Write-Host ""
Write-Host "[4/7] Router regression tests..."
docker compose run --rm --no-deps -v "${PWD}:/workspace" -w /workspace/backend -e PYTHONPATH=/workspace/backend backend pytest -q tests/test_data_requirement_router.py
if ($LASTEXITCODE -ne 0) { throw "Router regression failed" }

Write-Host ""
Write-Host "[5/7] Existing Track B regression baseline..."
docker compose run --rm --no-deps -v "${PWD}:/workspace" -w /workspace/backend -e PYTHONPATH=/workspace/backend backend pytest -q tests/test_track_b_hackathon.py
if ($LASTEXITCODE -ne 0) { throw "Track B regression failed" }

Write-Host ""
Write-Host "[6/7] Recreating backend only..."
docker compose up -d --force-recreate backend
if ($LASTEXITCODE -ne 0) { throw "Backend recreate failed" }

Write-Host ""
Write-Host "[7/7] Runtime route/capability verification..."
Start-Sleep -Seconds 4
docker compose exec -T backend python -c "from app.main import app; from app.services.planning_tools import get_tool; paths={r.path for r in app.routes}; p='/api/v1/projects/{project_id}/sites/{site_id}/terrain/dem'; print('DEM_ROUTE=',p in paths); print('TERRAIN_TOOL=',get_tool('terrain.site_summary')); assert p in paths; t=get_tool('terrain.site_summary'); assert t.deterministic and t.read_only"
if ($LASTEXITCODE -ne 0) { throw "Runtime verification failed" }

Write-Host ""
Write-Host "============================================================"
Write-Host "TERRAIN DEM INGESTION V1 GATE PASS"
Write-Host "Backend can now accept a strict single-band metric GeoTIFF DEM"
Write-Host "for an existing project/site and register it as data_role=dem."
Write-Host "No DEM was uploaded by this installer."
Write-Host "Next step: upload one real/demo DEM and run terrain acceptance."
Write-Host "============================================================"
